package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.math3.exception.MathArithmeticException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.MathArrays;
import org.apache.commons.math3.util.Pair;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for {@link DiscreteDistribution#sample(int)}.
 */
public class DiscreteDistribution_sample_TriageGen4Test {

    private List<Pair<Integer, Double>> samples;
    private DiscreteDistribution<Integer> distribution;

    @Before
    public void setUp() {
        samples = new ArrayList<>();
        samples.add(new Pair<>(1, 0.5));
        samples.add(new Pair<>(2, 0.5));
        distribution = new DiscreteDistribution<>(samples);
    }

    @Test
    public void testSample_PositiveSize() {
        int sampleSize = 5;
        Integer[] result = distribution.sample(sampleSize);

        assertNotNull(result);
        assertEquals(sampleSize, result.length);

        for (Integer val : result) {
            // Since weights are 0.5 for 1 and 2, values must be either 1 or 2
            org.junit.Assert.assertTrue(val == 1 || val == 2);
        }
    }

    @Test
    public void testSample_SizeOne() {
        int sampleSize = 1;
        Integer[] result = distribution.sample(sampleSize);

        assertNotNull(result);
        assertEquals(1, result.length);
        org.junit.Assert.assertTrue(result[0] == 1 || result[0] == 2);
    }

    @Test
    public void testSample_ZeroSizeThrowsException() {
        int sampleSize = 0;
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(sampleSize);
        });
    }

    @Test
    public void testSample_NegativeSizeThrowsException() {
        int sampleSize = -5;
        assertThrows(NotStrictlyPositiveException.class, () -> {
            distribution.sample(sampleSize);
        });
    }

    @Test
    public void testSample_TypeConsistency() {
        // Test with String to ensure generic array creation works correctly via reflection
        List<Pair<String, Double>> stringSamples = new ArrayList<>();
        stringSamples.add(new Pair<>("A", 1.0));
        DiscreteDistribution<String> stringDist = new DiscreteDistribution<>(stringSamples);

        String[] result = stringDist.sample(3);
        assertEquals(3, result.length);
        assertEquals("A", result[0]);
        assertEquals("A", result[1]);
        assertEquals("A", result[2]);
    }
}
